import {hearButton} from './play-media.mjs';
import {noticeCases} from './puppet-notice-content.mjs';
import {noticeView,noticeWords,renderNotice,startNotice,editNotice,supportNotice,tryNotice,keepNotice,recoverNotice} from './puppet-notice-core.mjs';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const button=(label,attrs,primary=false)=>`<button type="button" class="${primary?'primary':'secondary'}" ${attrs}>${esc(label)}</button>`;
const pages=['arrange','read','kept'],names={arrange:'Arrange',read:'Read',kept:'Keep'};
const printed=(s,label='Our printed draft')=>`<section class="notice-print"><h3>${esc(label)}</h3><p class="notice-line">${esc(renderNotice(s))}</p>${s.mark===null?'<p class="tiny">No ending mark yet.</p>':''}</section>`;
function chooser(v){return `<details class="notice-chooser" ${v.work?'':'open'}><summary>Choose either puppet notice</summary>${noticeCases.map(s=>{const old=v.cases.find(c=>c.id===s.id),bad=v.unreadable.some(c=>c.id===s.id);return `<article><h3>${esc(old?.work.source.title||s.title)}</h3><p>${esc(old?.work.source.purpose||s.purpose)}</p>${bad?'<p>This earlier request stays unreadable in your download. The other notice remains open.</p>':button(old?'Resume this notice':'Start this notice',`data-notice-start="${s.id}"`)}</article>`;}).join('')}${v.cases.filter(c=>!noticeCases.some(s=>s.id===c.id)).map(c=>`<article><h3>${esc(c.work.source.title)}</h3>${button('Resume earlier notice',`data-notice-start="${esc(c.id)}"`)}</article>`).join('')}</details>`;}
function response(r,current=false){const s=r.snapshot;return `<article class="notice-response" data-notice-record="${r.id}" ${current?`id="notice-response-${r.id}" data-notice-current-response`:""} tabindex="-1"><h3>${current?'Response to this version':'Earlier recorded response'} ${r.id}</h3>${current?'':printed(s,'Printed line in this response')}<p class="tiny">${r.scriptId===null?'Unmodeled arrangement. A person may understand it.':'An authored puppet response, not a general reading of English.'}</p><blockquote>${esc(r.reply)}</blockquote><p>${r.purposeFit===null?'The tiny script makes no purpose judgment for this arrangement.':r.purposeFit?'This authored script line serves this purpose card.':'This authored script line tells a different story from this purpose card.'}</p>${current?`<p class="notice-format">${esc(r.feedback)}</p>`:`<details><summary>About the capital and ending</summary><p>${esc(r.feedback)}</p></details>`}${hearButton(r.rendered+' '+r.reply+' '+r.feedback,current?'Hear this response':'Hear this earlier response')}</article>`;}
function exampleModel(w,step){const e=w.source.example,f=e.frames[step],s={source:{tokens:e.tokens},...f};return printed(s,step===1?'Unprinted example draft':'Supplied example line')+`<p>${esc(f.caption)}</p>${f.reply===null?'':`<p class="notice-example-reply"><strong>Supplied example response:</strong> ${esc(f.reply)}</p>`}`;}
function teaching(w){return `<details class="notice-help"><summary>Help with our printed line</summary><p>${esc(w.source.copy.help)}</p></details><details class="notice-example"><summary>A separate worked example</summary><p>Your own word tickets stay unchanged.</p><div data-notice-example-model data-step="0">${exampleModel(w,0)}</div><div class="notice-actions">${[0,1,2].map(i=>button('Example step '+(i+1),`data-notice-example-step="${i}" aria-pressed="${i===0}"`)).join('')}</div></details>`;}
function narration(v){if(!v.work)return 'Choose either puppet notice. Both are open.';const w=v.work;if(w.page==='kept')return v.kept?'Our kept version. '+renderNotice(v.kept.snapshot):v.keptUnreadable?'An earlier kept version cannot be read here. Its original record remains in notes.':'Nothing is kept for this notice yet. Unfinished work is welcome.';return (w.page==='arrange'?w.source.copy.intro:w.source.copy.responsePrompt)+' '+w.source.purpose+' Our current line: '+renderNotice(w)+(w.mark===null?' No ending mark yet.':'');}
export const noticeEntry=()=>'<section class="resume-strip notice-entry"><div><h2>The puppet notice printer</h2><p>Move words, try an ending, and discover another story.</p><a class="secondary" href="#loft/printer">Print a puppet notice</a></div></section>';
export function noticePage(state){
 const v=noticeView(state),head='<section class="notice-sheet" data-notice-root><a class="back" href="#loft">Back to Story Loft</a>',status='<p id="notice-status" role="status" tabindex="-1"></p>';
 if(v.status==='recovery')return head+'<h1 id="notice-title" tabindex="-1">An earlier printer notebook is kept</h1><p>It cannot be opened here. The complete original stays in your notes download.</p>'+button('Start a separate printer notebook','data-notice-recover')+status+'<a class="secondary" href="#notes">Grown-up notes and download</a></section>';
 if(!v.work)return head+'<h1 id="notice-title" tabindex="-1">Puppet Notice Printer</h1><p>Five word tickets. A new order can tell a new story.</p>'+chooser(v)+status+'<a class="secondary" href="#notes">Grown-up notes and download</a>'+(v.unreadable.length?button('Start a separate printer notebook','data-notice-recover'):'')+'</section>';
 const w=v.work,s=w.source,words=noticeWords(w);let body='';
 if(w.page==='arrange')body=`<ol class="notice-tickets">${w.order.map((key,i)=>`<li><div class="notice-ticket-word"><span class="notice-position">${i+1}</span><strong>${esc(words[i])}</strong></div><div class="notice-ticket-actions">${button('Earlier',`data-notice-move="${esc(key)}" data-delta="-1" aria-label="Move ${esc(words[i])}, word ${i+1}, earlier" ${i===0?'disabled':''}`)}${button('Later',`data-notice-move="${esc(key)}" data-delta="1" aria-label="Move ${esc(words[i])}, word ${i+1}, later" ${i===words.length-1?'disabled':''}`)}</div></li>`).join('')}</ol><fieldset><legend>First word capital</legend><div class="notice-actions">${[false,true].map(on=>button(on?'On':'Off',`data-notice-capital="${on}" aria-pressed="${w.capitalFirst===on}"`)).join('')}</div><p class="tiny">${esc(s.copy.nameCapitalNote)}</p></fieldset><fieldset><legend>Our ending</legend><div class="notice-actions">${[['.','Period .'],['?','Question mark ?'],['!','Exclamation mark !'],['','No ending yet']].map(([value,label])=>button(label,`data-notice-mark="${value}" aria-pressed="${w.mark===(value||null)}"`)).join('')}</div></fieldset>`;
 if(w.page==='read')body=`${v.readable.length>=4?`<p class="tiny">Trying now removes ${Math.max(0,v.readable.length-3)} older readable response(s), leaving four recent ones. The kept copy stays. Download notes first for a longer record.</p>`:''}${button('Try our printed notice','data-notice-try',true)}${v.feedback?response(v.feedback,true):'<p>No response to this exact version is showing. Try it, or keep exploring.</p>'}${button('Change our words','data-notice-page="arrange"')}`;
 if(w.page==='kept')body=v.kept?printed(v.kept.snapshot,'Our frozen kept version')+(v.kept.response?response(v.kept.response):'<p>This version was kept without a puppet response.</p>'):v.keptUnreadable?'<p>Your earlier kept version stays unreadable in the download. It cannot be overwritten. A separate printer notebook retains this whole notebook.</p>':'<p>No version is kept yet. Surprises and unfinished work are welcome.</p>';
 return head+`<p class="notice-eyebrow">Puppet Notice Printer · ${pages.indexOf(w.page)+1} of 3</p><h1 id="notice-title" tabindex="-1">${names[w.page]} our notice</h1><aside class="notice-purpose"><h2>${esc(s.title)}</h2><p>${esc(s.purpose)}</p></aside><p>${esc(w.page==='arrange'?s.copy.intro:w.page==='read'?s.copy.responsePrompt:'Keep this version, or return to change the current words.')}</p>${hearButton(narration(v),'Hear this turn').replace('<button ','<button data-notice-hear-current ')}${status}${w.page==='kept'?'':printed(w)}${body}<nav class="notice-actions" aria-label="Printer turns">${pages.map(p=>button(names[p],`data-notice-page="${p}" aria-current="${w.page===p?'page':'false'}"`)).join('')}</nav>${button(w.kept===null?'Keep this version':'Replace our kept version',`data-notice-keep ${v.keptUnreadable?'disabled':''}`)}${teaching(w)}${button('We thought together','data-notice-together')}<details><summary>Earlier responses (${v.readable.length})</summary>${v.readable.slice(-4).map(r=>response(r)).join('')}${v.raw.length?'<p>Some earlier responses are unreadable and remain in your download.</p>':''}</details>${chooser(v)}<details><summary>For a person to read</summary><p>These replies come from a tiny authored script. They do not grade your writing. A person may read, voice, sign or act out any arrangement.</p><a class="secondary" href="#loft">Try your own words in Story Loft</a><a class="secondary" href="#loft/instructions">Person-read Instructions</a></details><details><summary>Grown-ups: notes and recovery</summary><p>Supplied tickets, help and puppet responses are pictured practice. No independent reading, grammar level or writing quality is inferred.</p><a class="secondary" href="#notes">Download our notes</a>${button('Start a separate printer notebook','data-notice-recover')}</details></section>`;
}
export function noticeNotes(state){const v=noticeView(state);if(v.status==='missing')return '';if(v.status==='recovery')return '<section><h2>Puppet notices</h2><p>Earlier raw notebook retained in this download.</p></section>';return `<details class="panel"><summary>Puppet notices: supplied word tickets</summary><p>A finite authored script, not a grammar parser or person-read prose assessment. Full source, examples and raw siblings remain in the JSON download.</p>${v.cases.map(c=>`<section><h3>${esc(c.work.source.title)}</h3>${printed(c.work)}<p>Support: ${esc(c.work.support.join(', ')||'none recorded')}.</p>${c.readable.slice(-4).map(r=>response(r)).join('')}${c.kept?printed(c.kept.snapshot,'Kept version')+(c.kept.response?response(c.kept.response):''):''}${c.raw.length||c.keptUnreadable?'<p>Unreadable earlier work remains unchanged in this download.</p>':''}</section>`).join('')}${v.unreadable.length?'<p>Some earlier requests are unreadable; valid requests remain open.</p>':''}</details>`;}
export function bindNotice(state,{save,render,focus,canExport}){
 const scope=document.querySelector('[data-notice-root]');if(!scope)return;const bound=noticeView(state).root?.current??null;
 const live=b=>scope.isConnected&&b.isConnected&&scope.contains(b)&&(noticeView(state).root?.current??null)===bound;
 const message=text=>{const n=scope.querySelector('#notice-status');if(n)n.textContent=text;};
 const refusal='This change could not fit safely. Earlier work stays unchanged. Download notes, or use a separate explorer if the notebook is full.';
 const run=(fn,target)=>{if(!live(scope))return false;if(!fn()){message(refusal);return false;}save();render();if(target)focus(target);return true;};
 const click=(selector,fn)=>scope.querySelectorAll(selector).forEach(b=>b.addEventListener('click',e=>{if(live(b))fn(b,e);}));
 const supplied=(kind,e)=>{if(!live(scope))return false;if(!supportNotice(state,kind,canExport)){message(refusal);e?.stopImmediatePropagation();return false;}save();if(!noticeView(state).feedback)scope.querySelectorAll('[data-notice-current-response]').forEach(r=>{r.querySelector('h3').textContent='Earlier recorded response '+r.dataset.noticeRecord;r.removeAttribute('data-notice-current-response');});return true;};
 const confirm=(recover,fn)=>{if(!live(scope))return;const d=document.createElement('dialog');d.innerHTML=`<div class="dialog-content"><h2>${recover?'Start a separate printer notebook?':'Replace our kept version?'}</h2><p>${recover?'The entire earlier printer notebook stays in your download, including its kept copy.':'This overwrites the one earlier kept version for this notice.'} Download notes first if you want another copy.</p><button class="secondary" data-notice-cancel>Keep this page</button><button class="primary" data-notice-confirm>Yes, continue</button></div>`;document.body.append(d);d.showModal();d.querySelector('[data-notice-cancel]').onclick=()=>d.close();d.querySelector('[data-notice-confirm]').onclick=()=>{if(!d.isConnected||!d.open||!live(scope))return;d.close();run(fn,'#notice-title');};d.addEventListener('close',()=>d.remove());};
 click('[data-notice-start]',b=>run(()=>startNotice(state,b.dataset.noticeStart,canExport),'#notice-title'));
 click('[data-notice-page]',b=>run(()=>editNotice(state,'page',null,b.dataset.noticePage,canExport),'#notice-title'));
 click('[data-notice-move]',b=>{const key=b.dataset.noticeMove,delta=Number(b.dataset.delta);if(run(()=>editNotice(state,'move',key,delta,canExport))){const forward=`[data-notice-move="${key}"][data-delta="${delta}"]`,reverse=`[data-notice-move="${key}"][data-delta="${-delta}"]`;focus(document.querySelector(forward)?.disabled?reverse:forward);}});
 click('[data-notice-capital]',b=>run(()=>editNotice(state,'capital',null,b.dataset.noticeCapital==='true',canExport),`[data-notice-capital="${b.dataset.noticeCapital}"]`));
 click('[data-notice-mark]',b=>run(()=>editNotice(state,'mark',null,b.dataset.noticeMark||null,canExport),`[data-notice-mark="${b.dataset.noticeMark}"]`));
 click('[data-notice-try]',()=>{if(run(()=>tryNotice(state,canExport))){const v=noticeView(state);focus(`#notice-response-${v.feedback.id}`);}});
 click('[data-notice-keep]',()=>{const v=noticeView(state);if(v.keptUnreadable){message('The earlier kept copy remains in notes. Start a separate printer notebook to keep another version.');return;}if(v.work.kept!==null)confirm(false,()=>keepNotice(state,true,canExport));else if(run(()=>keepNotice(state,false,canExport))){document.querySelector('#notice-status').textContent='This version is kept.';focus('#notice-status');}});
 click('[data-notice-recover]',()=>confirm(true,()=>recoverNotice(state,canExport)));
 click('[data-notice-together]',(_b,e)=>{if(supplied('together',e))message('Thinking together is recorded.');});
 scope.querySelector('.notice-help')?.addEventListener('toggle',e=>{if(e.target.open&&!supplied('help',e))e.target.open=false;});
 scope.querySelector('.notice-example')?.addEventListener('toggle',e=>{if(e.target.open&&!supplied('example',e))e.target.open=false;});
 click('[data-notice-example-step]',(b,e)=>{if(!supplied('example',e))return;const step=Number(b.dataset.noticeExampleStep),model=scope.querySelector('[data-notice-example-model]');model.innerHTML=exampleModel(noticeView(state).work,step);model.dataset.step=String(step);scope.querySelectorAll('[data-notice-example-step]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));message('Example step '+(step+1)+'. Your own tickets stay unchanged.');});
 scope.querySelectorAll('[data-speak]').forEach(b=>b.addEventListener('click',e=>{if(!live(b)){e.stopImmediatePropagation();return;}if(b.hasAttribute('data-notice-hear-current'))b.dataset.speak=narration(noticeView(state));supplied('narrationRequested',e);}));
}
